  linkId: string;
  note?: string;
  created: Date;
  createdBy: AiChatAuthorInfo;

  /**
   * The role granted to anyone who redeems this link. Absent implies "build" for links created
   * before roles were introduced.
   */
  role?: CollaboratorRole;
};

