//   parser.streamingValue // => "hello world"

const JSON_SIMPLE_ESCAPES: Record<string, string | undefined> = {
  '"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f',
  'n': '\n', 'r': '\r', 't': '\t',
};

function isJsonWhitespace(ch: string): boolean {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r';
}

